    // Validate: only valid base64url characters
    if (!/^[A-Za-z0-9_-]*$/.test(s)) return null;
    let padded = s;
    const padLen = (4 - (padded.length % 4)) % 4;
    padded += "=".repeat(padLen);
    try {
      const binary = atob(padded);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
      return bytes;
    } catch {
      return null;
    }
  }

  function constantTimeEquals(a: Uint8Array, b: Uint8Array): boolean {
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) {
      diff |= a[i] ^ b[i];
    }
    return diff === 0;
  }

  async function generateToken(username: string): Promise<{ token: string; expiresAt: string }> {
    const nowMs = nowFn().getTime();
    const expMs = nowMs + 3_600_000;
    const nonce = crypto.getRandomValues(new Uint8Array(16));

    const payload = JSON.stringify({ u: username, e: expMs, n: toBase64url(nonce) });
    const payloadBytes = encoder.encode(payload);

    const key = await getKey();
    const sigBuf = await crypto.subtle.sign("HMAC", key, payloadBytes);
    const sigBytes = new Uint8Array(sigBuf);

    const token = toBase64url(payloadBytes) + "." + toBase64url(sigBytes);
    const expiresAt = new Date(expMs).toISOString();

    return { token, expiresAt };
  }

